#include "repair_detail.hpp"
#include "repair_acceptance.hpp"
#include "repair_service_sources.hpp"
#include "craft_facility_occupancy.hpp"
#include "resident/kernel/fixed_service_history.hpp"
namespace hanmo::resident {using namespace repair_detail;
namespace {
void distinct(const std::vector<StableId>&ids,const StableId&owner){for(std::size_t n=0;n<ids.size();++n){if(ids[n].empty())fail("RepairSourceReferenceRequired",owner);for(std::size_t k=0;k<n;++k)if(ids[k]==ids[n])fail("DuplicateRepairSourceReference",owner);}}
void actual_condition(const RepairReadContext&x,const RepairJob&j,const RepairCompletedSource&r){if(!r.condition_result_ref)fail("RepairConditionResultRequired",r.id);const auto*condition=take(read_item_condition_result(x.conditions,*r.condition_result_ref));if(condition->instance_id!=j.terms.instance_id||condition->source_kind!=ItemConditionSourceKind::repair_completed||!same_source_ref(condition->source_fact_ref,repair_completed_source(r.id))||!same_source_ref(condition->source_activity_ref,repair_job_source(j.id)))fail("RepairConditionBindingMismatch",r.id);}
}
Status validate_repair_jobs(const RepairReadContext&x){try{
 context(x);take(validate_repair_acceptances(x));if(!x.occupancy)fail("RepairOccupancyProviderRequired",{},ErrorKind::unsupported_capability);take(validate_craft_facility_occupancies(*x.occupancy));take(validate_repair_policy_catalog(x.policies,x.common_catalog));const auto at=now(x);NativeRepairActionTimeRead original(x);
 for(const auto&row:x.items.repair_jobs.jobs.rows()){
  const auto&j=*take(read_original_repair_job(x,row.first));if(j.id!=row.first)fail("RepairJobIdentityMismatch",row.first);distinct(j.claim_refs,j.id);distinct(j.control_refs,j.id);if(j.claim_refs.empty())fail("RepairClaimHistoryRequired",j.id);
  for(const auto&prior:x.items.repair_jobs.jobs.rows()){if(prior.first==row.first)break;if(prior.second.action_id==j.action_id||same_source_ref(prior.second.terms.accepted_service_ref.source_ref,j.terms.accepted_service_ref.source_ref))fail("DuplicateRepairOriginalExecution",j.id);}
  const auto*elapsed=find_fixed_elapsed(x.elapsed,j.action_id);if(!elapsed)fail("RepairElapsedHistoryRequired",j.id);const auto history=transitions(x,j);const auto proof=take(original.read_action_time_owner(repair_action_time_registration(),j.action_id));take(validate_action_time_owner_proof(repair_action_time_registration(),proof));take(original.validate_fixed_action_sources(repair_action_time_registration(),proof,*elapsed,history));
  ActionElapsedStore retained;retained.entries.emplace_back(*elapsed);retained.fixed_service_transitions=history;for(const auto&terminal:x.elapsed.terminal_bindings)if(terminal.action_ref==j.action_id)retained.terminal_bindings.push_back(terminal);take(validate_fixed_history_values(retained,at,x.scale,x.arithmetic_budget));
  const bool terminal=j.phase==RepairJobPhase::completed||j.phase==RepairJobPhase::interrupted;
  if(terminal){if(!std::holds_alternative<ElapsedTerminal>(elapsed->timing)||x.common.action(j.action_id))fail("RepairTerminalElapsedMismatch",j.id);const auto*actor=x.common.actor(j.terms.worker_id);if(actor&&actor->action_id==j.action_id)fail("RepairTerminalWorkerStillBound",j.id);}
  else{const auto*a=x.common.action(j.action_id);const auto*worker=x.common.actor(j.terms.worker_id);if(!a||a->kind!="repair"||a->actor_id!=j.terms.worker_id||a->participants!=std::vector<StableId>{j.terms.worker_id}||a->start_tick!=j.started_at.half_day_tick||a->remaining_ticks!=take(fixed_elapsed_remaining_ticks(*elapsed,x.scale,x.arithmetic_budget))||!worker||worker->action_id!=j.action_id||j.completed_ref||j.interrupted_ref||j.returned_ref)fail("RepairActiveActionMismatch",j.id);if((j.phase==RepairJobPhase::working)!=std::holds_alternative<ElapsedRunning>(elapsed->timing)||(j.phase==RepairJobPhase::suspended)!=std::holds_alternative<ElapsedSuspended>(elapsed->timing))fail("RepairPhaseTimingMismatch",j.id);const auto&item=lot(x.common,j.terms.original_item);if(item.item_instance_id!=std::optional<StableId>{j.terms.instance_id}||item.quantity!=1||item.reserved_by!=j.terms.service_holder||!owner(item.owner,j.terms.legal_owner))fail("RepairActiveCustodyMismatch",j.id);}
  if(j.phase==RepairJobPhase::completed){if(!j.completed_ref||j.interrupted_ref)fail("RepairCompletionReferenceRequired",j.id);take(read_actual_repair_completed(x,repair_completed_source(*j.completed_ref),j.terms.instance_id));actual_condition(x,j,*x.items.repair_jobs.completions.find(*j.completed_ref));}
  else if(j.phase==RepairJobPhase::interrupted){if(!j.interrupted_ref||j.completed_ref)fail("RepairInterruptionReferenceRequired",j.id);take(read_repair_interruption_source(x,{repair_interrupted_source(*j.interrupted_ref),1}));}
  if(j.returned_ref)take(x.original.validate_repair_return(j));
 }
 for(const auto&row:x.items.repair_jobs.controls.rows()){const auto&r=row.second;const auto*j=x.items.repair_jobs.jobs.find(r.job_id);if(!j||r.id!=row.first||std::count(j->control_refs.begin(),j->control_refs.end(),r.id)!=1||header(x.common,repair_control_source(r.id))<=header(x.common,repair_job_source(j->id))||compare(r.occurred_at,j->started_at)<0||compare(r.occurred_at,at)>0)fail("OrphanRepairControl",row.first);take(validate_original_repair_control(x,*j,r));}
 for(const auto&row:x.items.repair_jobs.completions.rows()){const auto&r=row.second;const auto*j=x.items.repair_jobs.jobs.find(r.job_id);if(!j||row.first!=r.id||j->completed_ref!=std::optional<StableId>{r.id})fail("OrphanRepairCompletion",row.first);take(read_actual_repair_completed(x,repair_completed_source(r.id),j->terms.instance_id));actual_condition(x,*j,r);}
 for(const auto&row:x.items.repair_jobs.interruptions.rows()){const auto&r=row.second;const auto*j=x.items.repair_jobs.jobs.find(r.job_id);if(!j||row.first!=r.id||j->interrupted_ref!=std::optional<StableId>{r.id}||j->phase!=RepairJobPhase::interrupted)fail("OrphanRepairInterruption",row.first);header(x.common,repair_interrupted_source(r.id));take(x.original.validate_repair_interruption(*j,r));}
 for(const auto&row:x.common.state().facts.rows()){const auto&f=row.second;if(f.domain!="crafting")continue;const bool missing=(f.kind=="repair_job"&&!x.items.repair_jobs.jobs.find(f.id))||(f.kind=="repair_control"&&!x.items.repair_jobs.controls.find(f.id))||(f.kind=="repair_completed"&&!x.items.repair_jobs.completions.find(f.id))||(f.kind=="repair_interrupted"&&!x.items.repair_jobs.interruptions.find(f.id));if(missing)fail("RepairOriginalSourceCoverageMismatch",f.id);}
 return common_success();
}catch(Failure&e){return {false,{},std::move(e.error)};}}
}
